-- ============================================================================
-- FC5: Relief & Flare Systems joins the catalog, the FIFTH Facilities course.
--
-- Catalog row (module 'facilities'; path_order 43, directly above FC4
-- gasprocessing at 42, FC3 rotating at 41, FC2 linesizing at 40 and FC1
-- separation at 39, and directly below FC6 heattransfer at 44; prereq_slug
-- NULL, the carried-over answer "no hard prerequisite inside a module") plus
-- the three capstones and their eighteen graded fields, generated by
-- tools/course-waves/relief/gen_course.py from fields.json, precision.json and
-- the capstone constants in fc5_fields_capstone.mjs. Deep seeds are three
-- separate migrations; the go-live is a fifth and is HELD until a NextGen
-- production upload carries the route /dashboard/apps/relief, because the 78
-- lessons, the teaching lab (reliefLab.js) and its three explorer panels ship
-- in the zip and not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. A relief valve is sized for a stated load
-- through a stated route, and the discipline is knowing which figure the engine
-- COMPUTED, which one somebody TYPED from a published chart or table, and which
-- one nothing in this package checks at all.
--
-- THE ENGINE. engines/facilities/relief.js (the four API 520 routes for gas,
-- subcritical gas, liquid and steam with the critical ratio, C, F2, Kv and KN;
-- the API 526 orifice ladder; the API 521 fire case from the exact wetted
-- segment to the relief load; the droplet dropout velocity and the horizontal
-- knockout drum; the point-source flare radiation asked as an intensity and as
-- a distance; and the adiabatic blowdown march). Vendored at engines 3bac13cd,
-- the FC5-0 repair, sha-identical over a closure of seven paths.
--
-- NOTHING GRADED DEPENDS ON A HELD, TYPED OR LIMIT ITEM, and each one is
-- neutralised by CONSTRUCTION. The liquid case is inviscid, so Kv is exactly 1
-- and no Kv fit constant enters. The valves are conventional, so Kb is 1 by the
-- standard, and the subcritical case uses F2 and ignores Kb. The steam case
-- relieves far below the Napier threshold, so KN is exactly 1. No orifice
-- letter and no fire duty is graded. The drum states its own dropout velocity,
-- so the sphere-drag correlation never runs. Both wetted heights are under
-- 25 ft. The flare states its own project allowable, which is none of the four
-- customary values. The go-live asserts all of it, on the keys and on the
-- values.
--
-- THE CAPSTONE GRADES WHAT THE COURSE TEACHES A READER TO GET RIGHT: that the
-- back pressure chooses the gas branch, that a gauge set pressure is not an
-- absolute relieving pressure, that a liquid level sets both the vapour area
-- and the fall distance of a drum, that a blowdown's end temperature is fixed
-- by the pressure ratio alone, and that a point source asked as a distance is
-- the same model asked backwards. All eighteen graded values were swept
-- against every number the digest prints and every number handed to a learner
-- in a prompt, at each field's own shipped tolerance.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('relief', 'Relief & Flare Systems', 'facilities', 43, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'relief', 'beginner', 'associate',
  'KOLO CREEK, a gas plant sized by API 520 for gas, liquid and steam relief',
  'Three fluids, one valve train, and the branch the back pressure decides',
  'KOLO CREEK, a gas plant with three relief cases on one train. Relieving pressures carry a 10 percent overpressure on the set pressure, and a gauge pressure becomes absolute by adding an atmosphere of 14.7 psia. THE GAS CASE: 37500 lb an hour through a conventional valve set at 385 psig, relieving at 165 degF, with a molecular weight of 23.5, a compressibility of 0.89 and a k of 1.31. The vendor states Kd 0.975, and Kb and Kc are both 1. It discharges first to a flare header at 55 psia, and then the SAME load and the SAME valve are read against a header already pressured to 330 psia. THE LIQUID CASE: 640 gpm through a valve set at 295 psig against a back pressure of 65 psig, with a specific gravity of 0.79 and no viscosity correction, because the service is taken as inviscid. The vendor states Kd 0.65, and Kw and Kc are both 1. THE STEAM CASE: 78000 lb an hour of saturated steam through a valve set at 585 psig. The vendor states Kd 0.975, and Kb, Kc and KSH are all 1. Report six values: the critical flow pressure ratio at the stated k, the gas coefficient C, the required gas area against the 55 psia header, the required gas area against the 330 psia header, the required liquid area and the required steam area. The ratio as a fraction, C as a number and every area in square inches, all to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','kolocreek_critical_pressure_ratio', 'label','The critical flow pressure ratio at the stated k', 'unit','fraction', 'expected',0.5439270375653221, 'tol',5e-07),
    jsonb_build_object('key','kolocreek_gas_coefficient_c', 'label','The gas coefficient C at the stated k', 'unit','USC coefficient', 'expected',347.9129792663607, 'tol',1e-06),
    jsonb_build_object('key','kolocreek_gas_critical_area_in2', 'label','The required gas area against the flare header back pressure', 'unit','in2', 'expected',1.227071995812397, 'tol',1e-06),
    jsonb_build_object('key','kolocreek_gas_subcritical_area_in2', 'label','The required gas area against the pressured header', 'unit','in2', 'expected',1.3771233172603285, 'tol',1e-06),
    jsonb_build_object('key','kolocreek_liquid_area_in2', 'label','The required liquid area', 'unit','in2', 'expected',1.429643931987363, 'tol',1e-06),
    jsonb_build_object('key','kolocreek_steam_area_in2', 'label','The required steam area', 'unit','in2', 'expected',2.3600699760747905, 'tol',1e-06)
  )
),
(
  'relief', 'intermediate', 'professional',
  'OGBAINBIRI, a flow station read as a fire case and a flare knockout drum',
  'The geometry a fire stands on, and the drum that keeps liquid out of the header',
  'OGBAINBIRI, a flow station. A horizontal vessel 9.5 ft in diameter and 37 ft long holds liquid to a level of 3.4 ft, and a vertical tower 7.2 ft in diameter and 32 ft tall stands beside it with liquid to 14.5 ft. The wetted area is the SHELL only, heads ignored, and neither wetted height reaches the 25 ft limit. The flare knockout drum at the end of the header is horizontal, 8.5 ft in diameter, with its liquid level at 0.35 of the diameter. It takes 168.0 actual cubic feet of vapour a second, and its design dropout velocity is stated as 2.05 ft a second, so no droplet is sized. The drum must hold the vapour for as long as a droplet takes to fall through the vapour space above the level. Then the diameter is taken to 10.5 ft at the same vapour rate, the same dropout velocity and the same level fraction. Report six values: the wetted shell area of the horizontal vessel, the wetted shell area of the tower, the fraction of the drum cross-section that lies below the liquid level, the vapour velocity through the space above it, the required drum length at 8.5 ft and the required drum length at 10.5 ft. The two wetted areas in ft2 to four decimals. The fraction, the velocity in ft a second and both lengths in ft to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ogbainbiri_wetted_area_ft2', 'label','The wetted shell area of the horizontal vessel', 'unit','ft2', 'expected',450.83862051383863, 'tol',0.0001),
    jsonb_build_object('key','ogbainbiri_tower_wetted_area_ft2', 'label','The wetted shell area of the vertical tower', 'unit','ft2', 'expected',327.9822730347744, 'tol',0.0001),
    jsonb_build_object('key','ogbainbiri_liquid_area_fraction', 'label','The fraction of the drum cross-section below the liquid level', 'unit','fraction', 'expected',0.3119188323905364, 'tol',5e-07),
    jsonb_build_object('key','ogbainbiri_vapor_velocity_fts', 'label','The vapour velocity through the space above the level', 'unit','ft/s', 'expected',4.302708032661933, 'tol',1e-06),
    jsonb_build_object('key','ogbainbiri_drum_length_ft', 'label','The required drum length at the first diameter', 'unit','ft', 'expected',11.5963228685157, 'tol',1e-06),
    jsonb_build_object('key','ogbainbiri_drum_length_wider_ft', 'label','The required drum length at the wider diameter', 'unit','ft', 'expected',9.387499464988899, 'tol',1e-06)
  )
),
(
  'relief', 'advanced', 'expert',
  'GBARAN, a compression station read as a blowdown and the flare it discharges to',
  'A vessel emptying itself, and the point source asked both ways',
  'GBARAN, a compression station. A vessel of 640 cubic feet holds gas at 1185 psia and 555 degR, with a molecular weight of 21.5, a k of 1.26 and a compressibility of 0.87 held constant throughout. The universal gas constant is 1545.349 ft lbf per lbmol degR. It depressures to 165 psia through an orifice of 1.375 inch diameter with a discharge coefficient of 0.84, against a flare back pressure of 16.5 psia. The gas in the vessel expands isentropically and the flow is taken as choked throughout, on the gas coefficient C at the stated k. The studio marches this at a time step of 0.1 s. The flare it discharges to releases 742000 kW, with a radiated fraction of 0.27 and a transmissivity of 0.91, read as a point source 118 m away. The project allowable is 5.25 kW per m2. Report six values: the gas inventory at the start in lb, the time to reach 165 psia in seconds, the gas temperature at 165 psia in degR, the vessel pressure below which the flow stops being choked in psia, the radiant intensity at 118 m in kW per m2, and the distance at which the intensity falls to the project allowable in m. The inventory to four decimals. Everything else to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','gbaran_initial_mass_lb', 'label','The gas inventory at the start of the blowdown', 'unit','lb', 'expected',3146.73713377691, 'tol',5e-05),
    jsonb_build_object('key','gbaran_blowdown_time_s', 'label','The time to reach the end pressure', 'unit','s', 'expected',183.65917528878765, 'tol',0.0001),
    jsonb_build_object('key','gbaran_final_temperature_degr', 'label','The gas temperature at the end pressure', 'unit','degR', 'expected',369.49595889955833, 'tol',1e-06),
    jsonb_build_object('key','gbaran_choked_floor_psia', 'label','The vessel pressure below which the flow stops being choked', 'unit','psia', 'expected',29.833914945452783, 'tol',5e-07),
    jsonb_build_object('key','gbaran_radiant_intensity_kwm2', 'label','The radiant intensity at the stated distance', 'unit','kW/m2', 'expected',1.0419219398921857, 'tol',5e-07),
    jsonb_build_object('key','gbaran_setback_distance_m', 'label','The distance at which the intensity falls to the project allowable', 'unit','m', 'expected',52.56781758753126, 'tol',1e-06)
  )
)
on conflict (app_slug, tier) do nothing;
